fn toggle_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            if ('a'..='z').contains(&c) {
                // lowercase to uppercase: subtract 32 from ASCII code
                ((c as u8) - 32) as char
            } else if ('A'..='Z').contains(&c) {
                // uppercase to lowercase: add 32 to ASCII code
                ((c as u8) + 32) as char
            } else {
                // non-ASCII letter, unchanged
                c
            }
        })
        .collect()
}